insert into public.papers(id,sample_author_id,author,category,title,blocks,tags,created_at) values
('bea56ed5-a763-5139-a78f-d8e4c8cb99ae','62c5b85f-d1f8-5f5e-a2de-7eab77823176','ねむり計測室','暮らし','二度寝にはなぜ第一回がないのか','[{"type":"text","heading":"観察メモ","body":"目覚ましを止めた時点で、睡眠はもう一度始まっている。つまり『二度寝』は起きる決断を一度だけ保留した状態では。"}]'::jsonb,ARRAY['朝','睡眠']::text[],now() - interval '297 hours'),
('25ded25c-76e7-5a3c-b825-7b25dd628778','7ced12c9-135d-56cc-a169-9539ee33a5e4','台所の観察者','食べもの','冷蔵庫の前で目的を忘れる','[{"type":"text","heading":"観察メモ","body":"扉を開けた瞬間、何を取りに来たか分からなくなる。冷蔵庫には記憶を冷却する機能まで付いているのだろうか。"}]'::jsonb,ARRAY['冷蔵庫','日常']::text[],now() - interval '294 hours'),
('b1abca90-d9be-5f23-8596-f0c4c51407e5','db53266a-6d71-5232-b35a-0be225fa9f57','通勤の窓際','暮らし','電車の空席は近づくと消える','[{"type":"text","heading":"観察メモ","body":"遠くから見えた席に向かう間に誰かが座る。席の存在は確定していたのに、所有権だけが未確定だった。"}]'::jsonb,ARRAY['電車','通勤']::text[],now() - interval '291 hours'),
('98366b61-6c6d-5ea0-ab15-fda78a1e79ae','0d63acdd-b5c0-5682-bb6c-7d1e1de055eb','返信保留中','人間関係','『いつでも返信して』が難しい理由','[{"type":"text","heading":"観察メモ","body":"いつでもいいと言われると、いつが一番いいか考えてしまう。自由は気楽さだけでなく、タイミングを自分で決める負担も運んでくる。"},{"type":"image","asset":"images/reply-at-night.jpg","caption":"この投稿のために生成した挿絵"}]'::jsonb,ARRAY['返信','会話']::text[],now() - interval '288 hours'),
('e9c9cf26-dd71-545c-8fe3-e25a8209f3dd','4607a90a-3eb4-5cb2-a6b7-c9a145cc79de','ポケットの数学','暮らし','傘を持つ確率より濡れる後悔','[{"type":"text","heading":"観察メモ","body":"降水確率を見て迷うが、選ぶ基準は確率だけではない。持ち歩く面倒さと、濡れたときの損失を別々に見積もると判断が変わる。"},{"type":"image","asset":"images/umbrella-choices.jpg","caption":"この投稿のために生成した挿絵"}]'::jsonb,ARRAY['確率','雨']::text[],now() - interval '285 hours'),
('6481d905-fc22-5009-8ad4-2668b3019eec','b17da883-163f-500d-b13b-5f5637787e9f','まちの余白','暮らし','ベンチのない街は急ぐ人向けか','[{"type":"text","heading":"観察メモ","body":"駅から家まで座れる場所が少ないと、移動しながら休むしかない。公共空間の設計は、歩き続けられる体を標準にしていないだろうか。"}]'::jsonb,ARRAY['街','社会']::text[],now() - interval '282 hours'),
('dbe5ac1d-3824-5355-bc25-8b16b7604707','53380863-84ea-56fa-822b-97a117ce48ef','オタクの棚','暮らし','積んだ本は未読ではなく未来の選択肢','[{"type":"text","heading":"観察メモ","body":"読んでいない本が増えると少し後ろめたい。でも棚にあるから、次の休日に手を伸ばせる。未読は可能性の在庫かもしれない。"}]'::jsonb,ARRAY['本','オタク']::text[],now() - interval '279 hours'),
('aaa9ba86-4e75-51a4-925e-92d1f033cc2e','7c500ff1-2e74-5d9b-adb2-bece30919a47','言葉の採集者','人間関係','『ちょっと』は長さを測らない','[{"type":"text","heading":"観察メモ","body":"『ちょっと待って』のちょっとは、時計の単位ではなく相手を待たせる気まずさを薄める言葉だと思う。"}]'::jsonb,ARRAY['言葉','時間']::text[],now() - interval '276 hours'),
('f4de6a4e-6f85-59bc-8461-d103ee4dbfa5','85768e26-eb90-58e2-a832-eac67f594703','ものの哲学','暮らし','片方の靴下はどこへ行くのか','[{"type":"text","heading":"観察メモ","body":"洗濯機を疑って探したが、発見場所はベッドの下。事件の規模は小さいのに、失踪という物語を与えた瞬間、捜査が楽しくなった。"},{"type":"image","asset":"images/sock-detective.jpg","caption":"この投稿のために生成した挿絵"}]'::jsonb,ARRAY['洗濯','靴下']::text[],now() - interval '273 hours'),
('b8a9adbe-b68c-55f6-8d79-08ceccf18c2a','95e7c850-fe1e-5942-9f47-4c59bf813cb0','雨の日統計','暮らし','雨音は作業用の背景になる','[{"type":"text","heading":"観察メモ","body":"窓の外の雨は聞こえるのに、隣の部屋の話し声ほど気にならない。意味のある音だけ脳が追いかけてしまうのか。"}]'::jsonb,ARRAY['雨','集中']::text[],now() - interval '270 hours'),
('524be286-2c33-5857-938b-20ec0e463d3f','62c5b85f-d1f8-5f5e-a2de-7eab77823176','ねむり計測室','暮らし','枕の冷たい面は有限資源である','[{"type":"text","heading":"観察メモ","body":"裏返した直後の幸福は大きい。でも三回目には裏も表も記憶を持ちはじめる。冷たさの供給には回復時間が必要だ。"}]'::jsonb,ARRAY['睡眠','観察']::text[],now() - interval '267 hours'),
('6c38eb5e-71a8-50dc-b22a-34fedc98f23a','7ced12c9-135d-56cc-a169-9539ee33a5e4','台所の観察者','食べもの','残り一口だけ妙に大事','[{"type":"text","heading":"観察メモ","body":"食べ始めは勢いで食べるのに、最後の一口は配分を考える。少ないほど価値を強く感じる、食卓の小さな希少性。"}]'::jsonb,ARRAY['食事','心理']::text[],now() - interval '264 hours'),
('6aed5b84-9140-59d1-97fd-6db6601827bd','db53266a-6d71-5232-b35a-0be225fa9f57','通勤の窓際','暮らし','いつもの道が工事中だと一日が新しい','[{"type":"text","heading":"観察メモ","body":"一本裏道に入っただけで知らない店が三つ見えた。毎日の移動は、景色を省略する技術でもある。"}]'::jsonb,ARRAY['街','散歩']::text[],now() - interval '261 hours'),
('ccf4e10f-7272-54d4-96ed-50d79083e03d','0d63acdd-b5c0-5682-bb6c-7d1e1de055eb','返信保留中','人間関係','既読より『書きかけ』が重い','[{"type":"text","heading":"観察メモ","body":"返事を考えて入力欄まで開いたのに、言葉が決まらない。相手には何も見えない時間に、こちらだけ長い会議をしている。"}]'::jsonb,ARRAY['返信','日常']::text[],now() - interval '258 hours'),
('b7e94701-db40-5f6d-9d8d-6d442cd03fe1','4607a90a-3eb4-5cb2-a6b7-c9a145cc79de','ポケットの数学','食べもの','レシートの合計は最後だけ驚く','[{"type":"text","heading":"観察メモ","body":"一品ずつは小さい金額でも、合計になると大きい。加算は簡単なのに、買い物中の頭は平均値で予算を見ている気がする。"}]'::jsonb,ARRAY['買い物','数']::text[],now() - interval '255 hours'),
('7638bf0e-44d6-5ba6-b97b-b8b2f7283036','b17da883-163f-500d-b13b-5f5637787e9f','まちの余白','暮らし','『無料』の作業は誰かの時間でできている','[{"type":"text","heading":"観察メモ","body":"町内の案内や地域イベントは、好意だけで回っているように見える。継続を考えるなら、見えない準備時間まで数えたい。"}]'::jsonb,ARRAY['地域','労働']::text[],now() - interval '252 hours'),
('30f26814-1a12-5d15-bf0c-0e76f10fe1f7','53380863-84ea-56fa-822b-97a117ce48ef','オタクの棚','暮らし','アニメの最終回後に部屋が静か','[{"type":"text","heading":"観察メモ","body":"毎週の予定が一つ消えると、時計より先に生活のリズムが変わる。作品への愛着には曜日も含まれていたのだ。"}]'::jsonb,ARRAY['アニメ','文化']::text[],now() - interval '249 hours'),
('26bf6081-23ca-52fb-9170-268a62cc1a94','7c500ff1-2e74-5d9b-adb2-bece30919a47','言葉の採集者','暮らし','雨上がりの『もう晴れた』','[{"type":"text","heading":"観察メモ","body":"雲が残っていても、傘を閉じられるなら晴れたと言う。天気の言葉は空だけでなく、自分の行動で決まる。"}]'::jsonb,ARRAY['雨','言葉']::text[],now() - interval '246 hours'),
('deffd176-6868-5e25-9de9-73bda9a1008f','85768e26-eb90-58e2-a832-eac67f594703','ものの哲学','暮らし','空の箱を捨てにくい','[{"type":"text","heading":"観察メモ","body":"中身があった時の役割を、箱がまだ覚えているように見える。実際には私が『いつか使う』という未来をしまっている。"}]'::jsonb,ARRAY['片付け','哲学']::text[],now() - interval '243 hours'),
('0c4f66bd-c66c-5c1f-a3ad-2376ef9444d3','95e7c850-fe1e-5942-9f47-4c59bf813cb0','雨の日統計','暮らし','天気予報を見たあと窓も見る','[{"type":"text","heading":"観察メモ","body":"画面の予報が正確でも、自分の家の前を確かめたい。広い地域の情報と、玄関を出る判断の間には最後の確認がある。"}]'::jsonb,ARRAY['天気','判断']::text[],now() - interval '240 hours'),
('15b5ee8e-3a85-54e1-82e1-80c9d22a0f82','62c5b85f-d1f8-5f5e-a2de-7eab77823176','ねむり計測室','暮らし','寝る前の一分は伸縮する','[{"type":"text","heading":"観察メモ","body":"歯磨き前の一分は短いのに、動画を『一本だけ』見る一分は三十分に育つ。時計より先に行動を定義した方がよさそう。"}]'::jsonb,ARRAY['夜','時間']::text[],now() - interval '237 hours'),
('91570fae-658d-5953-9173-7faae78996f4','7ced12c9-135d-56cc-a169-9539ee33a5e4','台所の観察者','食べもの','カレーは翌日の方が会話が上手い','[{"type":"text","heading":"観察メモ","body":"初日は具材が別々に自己紹介している。翌日は同じ話題でまとまっている。味の変化を人間関係にたとえると少し分かる。"}]'::jsonb,ARRAY['カレー','比喩']::text[],now() - interval '234 hours'),
('fe2b7458-df7e-5401-892b-b82ad9ec6c6c','db53266a-6d71-5232-b35a-0be225fa9f57','通勤の窓際','暮らし','信号待ちの二分は長い','[{"type":"text","heading":"観察メモ","body":"家での二分は一瞬なのに、横断歩道では長い。目的地が見えている時間は、待つことを余計に意識させる。"}]'::jsonb,ARRAY['時間','街']::text[],now() - interval '231 hours'),
('e90875ed-7bdc-53ce-b644-7b9de500b5a0','0d63acdd-b5c0-5682-bb6c-7d1e1de055eb','返信保留中','人間関係','雑談の『それで？』は小さな招待状','[{"type":"text","heading":"観察メモ","body":"内容を増やせという命令にも聞こえるが、続きを聞きたいという合図でもある。短い相づちの意味は関係性で変わる。"}]'::jsonb,ARRAY['会話','言葉']::text[],now() - interval '228 hours'),
('e02cae65-0721-5340-a546-8a5938dbd671','4607a90a-3eb4-5cb2-a6b7-c9a145cc79de','ポケットの数学','暮らし','五分の遅刻と五分の余裕は非対称','[{"type":"text","heading":"観察メモ","body":"同じ五分でも、遅刻には謝罪が付いて、余裕には何も付かない。時間の価値はゼロを境に急に曲がる。"}]'::jsonb,ARRAY['時間','数学']::text[],now() - interval '225 hours'),
('c9f4aaa2-8faf-54c2-99e6-1414848e448d','b17da883-163f-500d-b13b-5f5637787e9f','まちの余白','暮らし','駅前の木陰は小さなインフラ','[{"type":"text","heading":"観察メモ","body":"日差しの強い日に、木が一本ある場所だけ人の歩く速度が変わる。道路の幅だけでなく、立ち止まれる快適さも公共性だと思う。"}]'::jsonb,ARRAY['街','環境']::text[],now() - interval '222 hours'),
('d586cce8-2e04-5228-9f12-8600d311746a','53380863-84ea-56fa-822b-97a117ce48ef','オタクの棚','暮らし','推しの新情報で急に姿勢が良くなる','[{"type":"text","heading":"観察メモ","body":"通知を見る前は床に寝転んでいたのに、開くと座り直している。情報の重さは身体の角度に出る。"}]'::jsonb,ARRAY['推し','日常']::text[],now() - interval '219 hours'),
('4bded568-05b4-5144-8dee-ca6d482ccdeb','7c500ff1-2e74-5d9b-adb2-bece30919a47','言葉の採集者','人間関係','『普通は』と言う前に立ち止まる','[{"type":"text","heading":"観察メモ","body":"普通という言葉は便利だが、誰の経験を集めた普通なのかが省略される。説明を一行増やす方が、話は遠回りせずに済むことがある。"}]'::jsonb,ARRAY['言葉','社会']::text[],now() - interval '216 hours'),
('5ebf359c-d8cb-580a-9a63-88f30a822678','85768e26-eb90-58e2-a832-eac67f594703','ものの哲学','暮らし','鍵を探すとき鍵はいつも見ている','[{"type":"text","heading":"観察メモ","body":"最後に置いたのは自分のはず。持ち主の記憶より、物の現在位置の方が正確なのが少し悔しい。"}]'::jsonb,ARRAY['鍵','日常']::text[],now() - interval '213 hours'),
('1c76e10e-db03-5de4-9b2a-42437d9847b8','95e7c850-fe1e-5942-9f47-4c59bf813cb0','雨の日統計','暮らし','傘を忘れた日に限って降る気がする','[{"type":"text","heading":"観察メモ","body":"忘れた日だけ強く記憶に残り、持っていた日の小雨は数えていない。体感の確率を作る前に、忘れなかった日も記録してみたい。"}]'::jsonb,ARRAY['雨','確率']::text[],now() - interval '210 hours'),
('6c9a7e62-c2b9-5768-9363-8671c1dbd49f','62c5b85f-d1f8-5f5e-a2de-7eab77823176','ねむり計測室','暮らし','休日の朝、早く起きる謎','[{"type":"text","heading":"観察メモ","body":"平日は布団から出られない。休日は予定がなくても目が覚める。睡眠の敵は時刻ではなく『出勤する』という文脈かもしれない。"}]'::jsonb,ARRAY['休日','睡眠']::text[],now() - interval '207 hours'),
('2512bbed-33f2-5359-9ce1-381f2c709eef','7ced12c9-135d-56cc-a169-9539ee33a5e4','台所の観察者','食べもの','買い物メモに書いた物だけ忘れる','[{"type":"text","heading":"観察メモ","body":"頭に浮かんだ時点で安心してしまい、店ではメモを見ることも忘れる。記録は記憶の代わりになるが、記録の存在を覚える仕組みが必要。"}]'::jsonb,ARRAY['買い物','習慣']::text[],now() - interval '204 hours'),
('33df6f16-edc9-5829-8912-e1d6c239ec97','db53266a-6d71-5232-b35a-0be225fa9f57','通勤の窓際','暮らし','改札前で歩幅がそろう','[{"type":"text","heading":"観察メモ","body":"知らない人同士なのに、改札が近づくと自然に速度が似る。都市には音のない合図が多い。"}]'::jsonb,ARRAY['駅','観察']::text[],now() - interval '201 hours'),
('5ddf310d-4824-574e-9750-4daa66e2d6ec','0d63acdd-b5c0-5682-bb6c-7d1e1de055eb','返信保留中','人間関係','断る文面だけ丁寧になりすぎる','[{"type":"text","heading":"観察メモ","body":"断りたいという一点を伝えるために、前置きが四行になる。相手を尊重する言葉と、責任をぼかす言葉は似ている。"}]'::jsonb,ARRAY['断り方','言葉']::text[],now() - interval '198 hours'),
('5c143fcb-d660-590e-bcfe-1ae7a198ae3e','4607a90a-3eb4-5cb2-a6b7-c9a145cc79de','ポケットの数学','暮らし','行列の長さは待ち時間を教えない','[{"type":"text","heading":"観察メモ","body":"三人の列でも一人が大量購入なら長い。人数だけでなく、一人あたりの処理時間の分布を見る必要がある。短い列に毎回負ける理由が少し分かった。"}]'::jsonb,ARRAY['行列','確率']::text[],now() - interval '195 hours'),
('44cd93c6-d2fe-52f9-a280-2cfa59569a22','b17da883-163f-500d-b13b-5f5637787e9f','まちの余白','暮らし','便利なアプリの『前提』を数える','[{"type":"text","heading":"観察メモ","body":"スマホ、通信、読める文字、使える手、静かな場所。手続きが簡単になったと言うとき、何を持っている人の話なのか確認したい。"}]'::jsonb,ARRAY['社会','デジタル']::text[],now() - interval '192 hours'),
